struct Part { stem: u64, ord: u8 }
fn better(q: Part, a: Part, b: Part) -> bool {
    let ka = ((q.ord==a.ord) as u8, (q.stem==a.stem) as u8);
    let kb = ((q.ord==b.ord) as u8, (q.stem==b.stem) as u8);
    ka > kb
}

fn siblings(text: &str) -> Vec<String> {
    // after a full acc key, if the next chars are ", ." + digits, emit stem."."+digits
}
feats.push(Feat { id: vocab.intern(&format!("acc:{sib}")), w: 1.0, counts_len: false, inheritable: false });

fn years(text: &str) -> (Option<(i32,i32)>, Option<i32>) {
    let acc = acc_spans(text);
    let obj = four_digit_spans(text).filter(|s| !acc.covers(s));
    let acq = acc.iter().next().map(|a| a.left);
    (obj, acq)
}

fn sibling_year_wins(q_year: Option<i32>, a_year: i32, b_year: i32) -> Ordering {
    match q_year {
        Some(y) => (a_year==y).cmp(&(b_year==y)),
        None => Ordering::Equal, // date is not a tie-break
    }
}

fn counted<'a>(turn: &'a Turn, q_part: Option<u8>) -> &'a [u32] {
    match q_part {
        Some(p) => turn.part_tokens.get(&p).map(|v| v.as_slice()).unwrap_or(&turn.content_ids),
        None => &turn.content_ids,
    }
}

fn fill_set(pool: &mut Vec<usize>, stem: u64, by_suffix: &BTreeMap<i32, usize>) {
    for (_, ti) in by_suffix.range(..) {
        if !pool.contains(ti) { pool.push(*ti); }
    }
}

fn distinct(a: &TurnIx, b: &TurnIx) -> bool {
    a.acc_keys != b.acc_keys || a.acc_keys.is_empty()
}
// a title-equal pair with different keys both remain in the pool

fn is_measure(span: &str) -> bool {
    let Some((l,r)) = span.split_once('.') else { return false };
    r.len()==1 && l.chars().all(|c| c.is_ascii_digit())
}

fn tie_break(a: &TurnIx, b: &TurnIx, ga: u32, gb: u32) -> Ordering {
    gb.cmp(&ga).then(a.token_len.cmp(&b.token_len))
}

