    // segments between single quotes, then raw_tokens on the inside only
}

fn split_in(tokens: &[String]) -> (&[String], &[String]) {
    match tokens.iter().position(|t| t=="in") {
        Some(i) => (&tokens[..i], &tokens[i+1..]),
        None => (tokens, &[]),
    }
}

fn command_query(q: &str) -> bool {
    !q.ends_with('?') && !closed_class_first(q)
}
// pool: if command_query && groups>0 && line0_len<=12 { eligible even if t_scene was carried only by the short line }

