    // day + month-name + 4-digit, line 0 only
}

fn inventory_segments(line: &str) -> Option<Vec<String>> {
    let n = line.matches(',').count();
    if n < 3 { return None }
    Some(line.split(',').map(|s| s.trim().to_string()).collect())
}

fn vam_slots(text: &str) -> Slots {
    // prefix, body, acq_year from E.2601:2-1910; loc tokens dropped from len
}

fn outside_brackets(text: &str) -> String {
    // drop [ ... ] spans before year and entity harvest; keep them as a side list
}

fn script_alias(line: &str) -> Vec<String> {
    // split into ascii words and maximal non-ascii letter runs
}

fn alpha_acc(tok: &str) -> bool {
    let i = tok.find(|c: char| c.is_ascii_digit()).unwrap_or(tok.len());
    (2..=6).contains(&i) && (3..=6).contains(&(tok.len()-i))
        && tok[..i].chars().all(|c| c.is_ascii_alphabetic())
        && !tok.contains('-')
}

fn series_key(q: &[u32], df: &dyn Fn(u32)->u32, turn: &DetHashSet<u32>) -> (u32, i32) {
    let (mut p, mut s) = (0u32, 0i32);
    for &id in q { if turn.contains(&id) { if df(id)>=3 { s+=1 } else if df(id)==1 { p+=1 } } }
    (p, -s)
}

fn acc_credit(q: &Acc, t: &Acc) -> u8 {
    u8::from(q.stem==t.stem && q.suffix==t.suffix)
}

fn force_stem(pool: &mut Vec<usize>, stem: u64, index: &StemIndex) {
    for ti in index.turns(stem) {
        if !pool.contains(&ti) { pool.push(ti); }
    }
}

fn same_object(a: &TurnIx, b: &TurnIx) -> Option<bool> {
    if a.acc_keys.is_empty() && b.acc_keys.is_empty() { return None }
    Some(a.stem == b.stem && a.stem != 0)
}

fn keep_header(line: &str, repeats: u32) -> bool {
    repeats < 3 || line_has_acc_or_version(line)
}

fn fill_lot_behind(list: &mut Vec<usize>, prefix: u64, members: &[usize]) {
    if list.is_empty() { return }
    for &ti in members {
        if !list.contains(&ti) { list.push(ti); } // append, do not insert(0)
    }
}

fn bare_year(text: &str) -> Option<i32> {
    four_digits_outside_parens(text).next()
}

fn segment_of(line: &str, byte: usize) -> u16 {
    line[..byte].bytes().filter(|&b| b==b'.').count() as u16
}

fn prefix_before_date(line: &[Token]) -> &[Token] {
    match date_pos(line) { Some(i) => &line[..i], None => &[] }
}

fn letter_span(text: &str) -> Option<(u8,u8)> {
    // KEY letter en-dash letter, e.g. 13.220.62a–d
}

fn slash_span(text: &str) -> Option<(i32,i32)> {
    // 1258/1842 -> one pair, not two events
}

fn demote_span(q_quant: bool, a_span: bool, b_span: bool) -> Ordering {
    if q_quant { return Ordering::Equal }
    b_span.cmp(&a_span) // false (not a span) ranks first
}

fn owner_span(line: &[Token]) -> &[Token] {
    let i = line.iter().position(|t| t=="of");
    // slice after i until the next closed-class preposition
}

fn object_years(text: &str) -> Vec<i32> {
    let line0 = text.lines().next().unwrap_or("");
    four_digits_outside_parens(line0).filter(|y| !in_acc(line0, *y)).collect()
}

fn catch_join(a: &TurnIx, b: &TurnIx) -> bool {
    a.stem != 0 && a.stem == b.stem && a.last_content == b.first_content
}

fn rijks_id(tok: &str) -> bool {
    let p: Vec<&str> = tok.split('-').collect();
    p.len()==3 && (1..=4).contains(&p[0].len()) && p[1].len()==1
        && p[0].chars().all(|c| c.is_ascii_alphabetic())
        && p[1].chars().all(|c| c.is_ascii_alphabetic())
        && p[2].chars().all(|c| c.is_ascii_digit())
}

fn may_inherit(p: &Part, c: &Part) -> bool {
    p.stem==c.stem && p.suffix<c.suffix && (p.ord==0 || p.ord==c.ord)
}

fn alias_hit(q: &DetHashSet<u32>, t: &TurnIx) -> u32 {
    q.intersection(&t.quoted).count() as u32 + q.intersection(&t.script).count() as u32
}

fn side_score(q: &Set, t: &TurnIx) -> (u32, u8) {
    let c = overlap(q, &t.contents); let k = overlap(q, &t.container);
    if c>k { (c, 1-u8::from(t.inventory)) } else { (0, 0) }
}

fn if_key(cmd: bool, inv: bool, groups: u32, len: u32) -> Option<(u32,u8,i32)> {
    if !cmd { return None }
    Some((groups, 1-u8::from(inv), -(len as i32)))
}

fn event_triple(line: &str) -> Option<(i32,u8,u8)> {
    let masked = mask_acc(line);
    parse_day_month_year(&masked)
}

fn event_bits(s: &Slots, q_year: i32) -> (u8, u8) {
    (u8::from(s.span_contains(q_year)), 0) // acq and loc forced to 0
}

fn eligible_years(text: &str) -> Vec<i32> {
    four_digits(text).filter(|y| !in_brackets(text,*y) && !after_after(text,*y)).collect()
}

fn numeric_answer(t: &TurnIx) -> Option<i32> {
    t.range_width // None means leave the WH voter alone
}

fn earlier_if_named(q: Option<i32>, a: i32, b: i32) -> Ordering {
    match q { Some(y) => (a==y).cmp(&(b==y)), None => Ordering::Equal }
}

fn order_set(q_suffix: Option<i32>, q_all: bool, t_suffix: i32) -> (u8, i32) {
    if q_all { (u8::from(Some(t_suffix)==q_suffix), -t_suffix) }
    else { (u8::from(Some(t_suffix)==q_suffix), 0) }
}

fn print_key(exact: bool, private_hits: u32, shared_hits: u32) -> (u8, u32, i32) {
    (u8::from(exact), private_hits, -(shared_hits as i32))
}

fn forbid_join(a: &TurnIx, b: &TurnIx) -> bool {
    !a.acc_keys.is_empty() && !b.acc_keys.is_empty() && a.acc_keys.is_disjoint(&b.acc_keys)
}

fn header_fate(repeats: u32, keys: usize) -> HeaderFate {
    if repeats>=3 && keys==0 { HeaderFate::Drop } else if keys>0 { HeaderFate::KeepNoLen } else { HeaderFate::Keep }
}

fn num_class(d: i32) -> Class {
    let w = width(d);
    if w<=3 { Class::Plate } else if w==4 { Class::Year } else { Class::Other }
}

fn tie(qa: u32, qb: u32, da: u32, db: u32, la: u32, lb: u32) -> Ordering {
    if qa!=qb { return Ordering::Equal }
    da.cmp(&db).then(la.cmp(&lb))
}

fn counted_part(t: &TurnIx, q: &Acc) -> &[u32] {
    match t.parts.iter().find(|p| q.keys.contains(&p.key)) {
        Some(p) => &p.tokens, None => &t.content_ids,
    }
}

fn seat_run(suffixes: &[(i32, usize)], all: bool) -> Vec<usize> {
    if !all { return vec![] }
    let mut v = suffixes.to_vec(); v.sort_by_key(|s| s.0); v.into_iter().map(|s| s.1).collect()
}

fn events(t: &TurnIx) -> Vec<(i32,i32)> {
    let mut e = t.slash_spans.clone();
    e.retain(|s| !t.acq_years.contains(&s.0) && !t.acq_years.contains(&s.1));
    e
}

fn alias_leads(q: &Set, t: &TurnIx) -> (u8, u32) {
    let n = overlap(q, &t.owner.union(&t.quoted));
    if n>0 { (1, n) } else { (0, overlap(q, &t.content)) }
}

fn joint(prefix_hit: bool, triple_hit: bool, ymd: i32) -> (u8, i32) {
    (u8::from(prefix_hit && triple_hit), ymd)
}

fn class_num(span: &str) -> NumClass {
    if measure_one_decimal(span) { NumClass::Measure }
    else if width(span)==4 { NumClass::Year }
    else { NumClass::TitleInt }
}

fn edge(a: &TurnIx, b: &TurnIx) -> bool {
    a.stem!=0 && a.stem==b.stem && a.last_content==b.first_content
}

fn year_key(q: i32, bare: Option<i32>, paren: Option<(i32,i32)>) -> (u8,u8,i32) {
    (u8::from(bare==Some(q)), u8::from(paren.is_some_and(|p| q>=p.0 && q<=p.1)), -(bare.unwrap_or(0)))
}

fn part_eq(q: &Vam, t: &Vam) -> bool {
    q.prefix==t.prefix && q.body==t.body && q.part==t.part && q.acq==t.acq
}

fn id_over_alias(id_hit: bool, alias_hit: bool, groups: u32) -> (u8,u8,u32) {
    (u8::from(id_hit), u8::from(alias_hit), groups)
}

fn event_count(t: &TurnIx) -> usize {
    t.line0_spans.iter().filter(|s| !t.mention_years.contains(&s.0)).count()
}

fn branch(all: bool, width: i32, exact: bool, span: bool) -> (u8, i32) {
    if all { (1, width) } else { (u8::from(exact), -i32::from(span)) }
}

fn full_date_match(q: Option<(i32,u8,u8)>, t: (i32,u8,u8)) -> bool {
    q.is_some_and(|d| d==t)
}

fn paren_alias(line: &str) -> Vec<String> {
    // inside '(' ')', keep both ascii tokens and non-ascii runs
}

fn frag_rule(a: &TurnIx, b: &TurnIx) -> Option<Ordering> {
    if a.acc_keys.is_empty() && b.acc_keys.is_empty() { return None }
    if a.stem!=b.stem { return Some(a.token_len.cmp(&b.token_len)) }
    None
}

fn admit(cmd: bool, line0: usize, groups: u32) -> bool {
    cmd && groups>0 && line0<=12
}

fn alpha_hit(original: &str, q: &str) -> bool {
    original.split_whitespace().any(|t| t.trim_matches(|c: char| !c.is_ascii_alphanumeric())==q)
        && !dotted_component(original, q)
}

fn contents_triple(tokens: &[Token]) -> Option<(i32,u8,u8)> {
    let (c, _) = split_in_tokens(tokens);
    parse_day_month_year(c)
}

fn fate_after_loc(line: &str, repeats: u32) -> HeaderFate {
    let kept = delete_loc(line);
    if repeats>=3 && acc_keys(&kept).is_empty() { HeaderFate::Drop } else { HeaderFate::Keep }
}

fn alias_outside(text: &str) -> Vec<String> {
    script_runs(text).filter(|r| !inside_brackets(text, r)).collect()
}

fn no_recency(title_eq: bool, span_eq: bool, exact: bool) -> bool {
    title_eq && span_eq && !exact // caller must not swap
}

fn rotate_front(run: &mut Vec<usize>, named: usize) {
    if let Some(i) = run.iter().position(|t| *t==named) { let t = run.remove(i); run.insert(0, t); }
}

fn pin(q_ver: Option<&str>, handles: &[String]) -> u8 {
    u8::from(q_ver.is_some_and(|v| handles.iter().any(|h| h==v)))
}

fn event_hit(class: NumClass, seg: u16, title_seg: u16) -> bool {
    matches!(class, NumClass::Year | NumClass::Span) && seg==title_seg
}

fn lead(exact: bool, inherited_hits: u32) -> (u8, u32) {
    if exact { (1, 0) } else { (0, inherited_hits) }
}

fn registry_seat(q_ver: Option<&str>, pin: bool, current: bool) -> Option<u8> {
    if q_ver.is_some() { Some(u8::from(pin)) } else if current { Some(1) } else { None }
}

fn sibling_year(t: &TurnIx) -> Option<i32> {
    t.object_year.filter(|y| !t.acq_years.contains(y) && !t.credit_years.contains(y))
}
